/**
 * Fixed-capacity LRU cache backed by a hash map and an index-based doubly
 * linked list stored in typed arrays. All operations run in O(1) expected time.
 */
export class LruCache {
  readonly capacity: number;
  readonly #index = new Map<string, number>();
  readonly #keys: string[];
  readonly #values: string[];
  readonly #prev: Int32Array;
  readonly #next: Int32Array;
  /** Most recently used slot, or -1 when empty. */
  #head = -1;
  /** Least recently used slot, or -1 when empty. */
  #tail = -1;
  /** Next never-used slot. */
  #fresh = 0;
  /** Stack of released slots available for reuse. */
  readonly #free: number[] = [];

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError(`capacity must be a positive integer, got ${capacity}`);
    }
    this.capacity = capacity;
    this.#keys = new Array<string>(capacity);
    this.#values = new Array<string>(capacity);
    this.#prev = new Int32Array(capacity);
    this.#next = new Int32Array(capacity);
  }

  get size(): number {
    return this.#index.size;
  }

  get(key: string): string | undefined {
    const slot = this.#index.get(key);
    if (slot === undefined) return undefined;
    this.#moveToFront(slot);
    return this.#values[slot];
  }

  set(key: string, value: string): void {
    const existing = this.#index.get(key);
    if (existing !== undefined) {
      this.#values[existing] = value;
      this.#moveToFront(existing);
      return;
    }
    if (this.#index.size >= this.capacity) this.#evict();
    const slot = this.#allocate();
    this.#keys[slot] = key;
    this.#values[slot] = value;
    this.#index.set(key, slot);
    this.#pushFront(slot);
  }

  delete(key: string): boolean {
    const slot = this.#index.get(key);
    if (slot === undefined) return false;
    this.#index.delete(key);
    this.#release(slot);
    return true;
  }

  #allocate(): number {
    return this.#free.pop() ?? this.#fresh++;
  }

  #release(slot: number): void {
    this.#unlink(slot);
    this.#keys[slot] = '';
    this.#values[slot] = '';
    this.#free.push(slot);
  }

  #evict(): void {
    const slot = this.#tail;
    if (slot < 0) return;
    const key = this.#keys[slot];
    if (key !== undefined) this.#index.delete(key);
    this.#release(slot);
  }

  #unlink(slot: number): void {
    const prev = this.#prev[slot] ?? -1;
    const next = this.#next[slot] ?? -1;
    if (prev >= 0) this.#next[prev] = next;
    else this.#head = next;
    if (next >= 0) this.#prev[next] = prev;
    else this.#tail = prev;
  }

  #pushFront(slot: number): void {
    this.#prev[slot] = -1;
    this.#next[slot] = this.#head;
    if (this.#head >= 0) this.#prev[this.#head] = slot;
    else this.#tail = slot;
    this.#head = slot;
  }

  #moveToFront(slot: number): void {
    if (slot === this.#head) return;
    this.#unlink(slot);
    this.#pushFront(slot);
  }
}

import { readFileSync, writeSync } from 'node:fs';
import { LruCache } from './lru.ts';

/** Runs the command script in `input` and returns the output lines. */
export function run(input: string): string[] {
  const out: string[] = [];
  let cache: LruCache | undefined;
  let pos = 0;
  const end = input.length;

  while (pos < end) {
    let eol = input.indexOf('\n', pos);
    if (eol < 0) eol = end;
    let lineEnd = eol;
    if (lineEnd > pos && input.charCodeAt(lineEnd - 1) === 13 /* \r */) lineEnd--;
    const line = input.slice(pos, lineEnd);
    pos = eol + 1;
    if (line.length === 0) continue;

    if (cache === undefined) {
      cache = new LruCache(Number.parseInt(line, 10));
      continue;
    }

    const sp1 = line.indexOf(' ');
    const cmd = sp1 < 0 ? line : line.slice(0, sp1);
    switch (cmd) {
      case 'SET': {
        const sp2 = line.indexOf(' ', sp1 + 1);
        if (sp2 < 0) break;
        cache.set(line.slice(sp1 + 1, sp2), line.slice(sp2 + 1));
        break;
      }
      case 'GET':
        if (sp1 >= 0) out.push(cache.get(line.slice(sp1 + 1)) ?? 'NULL');
        break;
      case 'DEL':
        if (sp1 >= 0) out.push(cache.delete(line.slice(sp1 + 1)) ? '1' : '0');
        break;
      case 'SIZE':
        out.push(String(cache.size));
        break;
      default:
        break;
    }
  }
  return out;
}

function writeAll(fd: number, data: Buffer): void {
  let offset = 0;
  while (offset < data.length) {
    try {
      offset += writeSync(fd, data, offset);
    } catch (e) {
      if (Error.isError(e) && (e as NodeJS.ErrnoException).code === 'EAGAIN') continue;
      throw e;
    }
  }
}

if (import.meta.main) {
  const input = readFileSync(0).toString('latin1');
  const lines = run(input);
  if (lines.length > 0) writeAll(1, Buffer.from(lines.join('\n') + '\n', 'latin1'));
}

